//! Required LI value signed-long reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><li id=list value=-7 type=marker>Fallback list item</li><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://li-value.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn li_value_canonical_accessor_and_initial_signed_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),a=Object.getOwnPropertyDescriptor(HTMLLIElement.prototype,'value');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get value'||a.set.name!=='set value'||Object.hasOwn(x,'value')||x.value!==-7||x.type!=='marker')throw 'canonical list-item signed value';");}
#[test]
fn li_value_numeric_assignment_wraps_and_preserves_actual_attr(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),attr=x.getAttributeNode('value'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.value=2147483648;var records=watch.takeRecords();if(x.value!==-2147483648||attr.value!=='-2147483648'||x.getAttributeNode('value')!==attr||records.length!==1||records[0].oldValue!=='-7'||x.type!=='marker')throw 'signed long wrapping and real transaction';");}
#[test]
fn li_value_inert_getter_integer_prefix_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:li');x.setAttribute('value','  +0031tail');if(!(x instanceof HTMLLIElement)||x.value!==31)throw 'inert HTML integer parsing';var attr=x.getAttributeNode('value'),copy=x.cloneNode(false);if(copy.value!==31||copy.getAttributeNode('value')===attr||copy.getAttribute('value')!=='  +0031tail')throw 'independent actual integer backing';x.setAttribute('value','2147483648');if(x.value!==0||x.getAttributeNode('value')!==attr||attr.value!=='2147483648')throw 'out of range getter default without rewrite';");}

#[test]
fn li_value_getter_html_integer_prefixes_defaults_and_exact_namespaces(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('list'),new Document().createElementNS('http://www.w3.org/1999/xhtml','t:li')]){x.removeAttribute('value');if(x.value!==0)throw 'absent long default';x.setAttributeNS('urn:foreign','value','91');x.setAttributeNS(null,'VALUE','92');if(x.value!==0)throw 'exact long namespace and case';for(var pair of [['',0],['  +0031tail',31],['-2147483648x',-2147483648],['2147483647.9',2147483647],['2147483648',0],['-2147483649',0],['0x10',0],['3.9',3],['-.1',0],['--1',0],['\u00a0 3',0],[' \t\n\f\r-0junk',0],['+0000030tail',30],['+',0],['-1e10',-1],['0000000000000000012',12]]){x.setAttributeNS(null,'value',pair[0]);var attr=x.getAttributeNodeNS(null,'value');if(typeof x.value!=='number'||x.value!==pair[1]||attr.value!==pair[0]||x.getAttributeNodeNS(null,'value')!==attr)throw 'HTML long prefix without normalization';}x.setAttributeNS(null,'value','-0');if(1/x.value!==Infinity)throw 'positive zero read';}"#);}
#[test]
fn li_value_setter_number_conversion_and_webidl_signed_wrap(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('list'),new Document().createElementNS('http://www.w3.org/1999/xhtml','li')]){x.type='marker';for(var pair of [['3.9',3],['0x10',16],[true,1],[false,0],[null,0],[undefined,0],[NaN,0],[Infinity,0],[-Infinity,0],[-0,0],[2147483647,2147483647],[2147483648,-2147483648],[4294967295,-1],[4294967296,0],[-2147483649,2147483647],[-4294967295,1],[4294967297.9,1],[-3.9,-3],['  +31  ',31]]){x.value=pair[0];if(x.value!==pair[1]||x.getAttribute('value')!==String(pair[1])||x.type!=='marker')throw 'WebIDL signed-long assignment';}Object.getOwnPropertyDescriptor(HTMLLIElement.prototype,'value').set.call(x);if(x.value!==0||x.getAttribute('value')!=='0')throw 'missing numeric argument';}"#);}
#[test]
fn li_value_once_number_conversion_reentry_abrupt_and_non_number_primitives(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),old=x.getAttributeNode('value'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.value={valueOf:function(){calls++;x.removeAttribute('value');x.setAttribute('value','author');return 2147483648;},toString:function(){throw 'wrong hint';}};var current=x.getAttributeNode('value'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='-7'||current.value!=='-2147483648'||records.length!==3||records[2].oldValue!=='author')throw 'once numeric conversion with current Attr';var order='';x.value={valueOf:function(){order+='v';return {};},toString:function(){order+='s';return '17';}};if(order!=='vs'||x.value!==17||current!==x.getAttributeNode('value'))throw 'number-hint fallback order';watch.takeRecords();var marker={},caught;try{x.value={valueOf:function(){x.setAttribute('value','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.getAttribute('value')!=='author effect'||records.length!==1||records[0].oldValue!=='17')throw 'abrupt numeric author effect';for(var bad of [Symbol('number'),BigInt(1)]){caught=false;try{x.value=bad;}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.getAttribute('value')!=='author effect')throw 'implicit numeric primitive refusal';}var hints='',value={};value[Symbol.toPrimitive]=function(hint){hints+=hint;return NaN;};x.value=value;if(hints!=='number'||x.value!==0||x.getAttribute('value')!=='0'||x.type!=='marker')throw 'number primitive hint';"#);}
#[test]
fn li_value_concrete_brands_precede_conversion_and_author_shadows(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),C=HTMLLIElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'value'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('ul'),document.getElementById('neighbor'),document.createElement('data'),document.createElementNS('urn:foreign','li'),new Document().createElementNS('http://www.w3.org/1999/xhtml','LI')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'long getter concrete brand';caught=false;try{a.set.call(bad,{valueOf:function(){calls++;return 1;}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'long setter brand before conversion';}Object.defineProperty(x,'value',{value:'author',writable:true,configurable:true});a.set.call(x,3.9);if(x.value!=='author'||a.get.call(x)!==3||x.getAttribute('value')!=='3')throw 'canonical numeric authority';delete x.value;delete window.HTMLLIElement;var copy=x.cloneNode(false);if(x.value!==3||!(copy instanceof C)||Object.getPrototypeOf(copy)!==P||copy.value!==3||document.getElementById('neighbor').value!=='seed')throw 'saved canonical long interface';"#);}
#[test]
fn li_value_raw_attribute_backing_and_numeric_normalization_keep_exact_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('list'),new Document().createElementNS('http://www.w3.org/1999/xhtml','li')]){x.setAttribute('value','12\ud800Z');var attr=x.getAttributeNode('value');if(x.value!==12||attr.value.length!==4||attr.value.charCodeAt(2)!==55296)throw 'actual raw integer prefix';attr.nodeValue='-2\udfffZ';if(x.value!==-2||attr.value.length!==4||attr.value.charCodeAt(2)!==57343)throw 'raw Attr integer alias';var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.value=4294967295;var records=watch.takeRecords();if(x.value!==-1||attr.value!=='-1'||x.getAttributeNode('value')!==attr||records.length!==1||records[0].oldValue!=='-2\udfffZ'||records[0].oldValue.charCodeAt(2)!==57343)throw 'numeric normalization exact old backing';x.setAttribute('value','7\ud800');var copy=x.cloneNode(false);if(copy.value!==7||copy.getAttribute('value').length!==2||copy.getAttribute('value').charCodeAt(1)!==55296||copy.getAttributeNode('value')===attr)throw 'raw integer independent clone';copy.value=-0;if(copy.value!==0||copy.getAttribute('value')!=='0'||x.value!==7||attr.value.charCodeAt(1)!==55296)throw 'independent numeric clone write';}"#);}
#[test]
fn li_value_native_adoption_copy_import_and_shallow_template_preserve_metadata(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),attr=x.getAttributeNode('value'),first=x.firstChild,copy=x.cloneNode(true),doc=new Document();if(copy.value!==-7||copy.firstChild===first||copy.getAttributeNode('value')===attr)throw 'actual numeric clone';doc.adoptNode(x);if(x.value!==-7||x.ownerDocument!==doc||attr.ownerDocument!==doc||x.firstChild!==first||x.getAttributeNode('value')!==attr)throw 'identity numeric adoption';var imported=document.importNode(x,true);if(imported.value!==-7||imported.ownerDocument!==document||imported.firstChild===first||imported.getAttributeNode('value')===attr)throw 'actual numeric import';document.adoptNode(x);document.body.appendChild(x);copy.value=42;if(x.value!==-7||copy.value!==42||x.firstChild!==first||x.type!=='marker')throw 'independent numeric lifecycle';var leaf=x.cloneNode(false),template=document.createElement('template');template.content.appendChild(leaf);document.body.appendChild(template);if(leaf.value!==-7||leaf.ownerDocument!==template.content.ownerDocument||leaf.getAttribute('value')!=='-7')throw 'actual numeric template parking';");}
#[test]
fn li_value_saved_child_origin_refuses_before_number_hooks_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),calls=0,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLLIElement.prototype,'value');a.set.call(x,2147483648);if(a.get.call(x)!==-2147483648)throw 'same origin signed accessor';");p.set_location(&crate::navigation::address("https://foreign-li-value.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for code in ["a.get.call(x);","a.set.call(x,{valueOf:function(){calls++;return 1;}});"]{p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://li-value.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||x.value!==-2147483648)throw 'origin refusal before coercion';a.set.call(x,-3.9);if(a.get.call(x)!==-3||x.getAttribute('value')!=='-3')throw 'fresh numeric owner recovery';");}
#[test]
fn li_value_reads_charge_payload_and_deadline_without_copy_string_or_retained_growth(){for inert in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','li');"}else{"var x=document.getElementById('list');"});run(&mut d,&mut f,&mut p,&format!("x.setAttribute('value','{}7');","0".repeat(128)));let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("genuine LI")};let before=format!("{:?}",d.nodes);let retained=p.state.retained;let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),2=>p.state.host_work=16,_=>{p.state.retained_limit=retained;p.state.copy_work=0;p.state.limits.host.string_bytes=0;}}let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.li_value_get(object);if mode==3{assert!(matches!(result,Ok(Value::Number(7.0))));}else{assert!(result.is_err());}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.retained,retained);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.li_value_get(object),Ok(Value::Number(7.0))));}}}
#[test]
fn li_value_writer_refusal_preserves_records_observers_and_recovers(){for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','li');"}else{"var x=document.getElementById('list');x.removeAttribute('value');"});run(&mut d,&mut f,&mut p,"var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=0,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute("x.value=42;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.value!==0||x.hasAttribute('value')||watch.takeRecords().length)throw 'atomic numeric refusal';x.value=42;var records=watch.takeRecords();if(x.value!==42||x.getAttribute('value')!=='42'||records.length!==1||records[0].oldValue!==null)throw 'fresh numeric writer recovery';");}}}

#[test]
fn li_value_clone_import_promotion_refusal_is_atomic_and_recovers(){
 for tag in ["li"]{for operation in ["clone","import","promote"]{for mode in 0..5{
  // Promotion reuses reserved main slots; its node limit is tested as a no-growth success below.
  if operation=="promote"&&mode==3{continue;}
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=match operation{
   "clone"=>{run(&mut d,&mut f,&mut p,"source=document.getElementById('list');");"var result=source.cloneNode(true);"},
   "import"=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.value=42;source.appendChild(doc.createTextNode('Fallback'));");"var result=document.importNode(source,true);"},
   _=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.value=42;source.appendChild(doc.createTextNode('Fallback'));");"var result=target.appendChild(source);"}
  };
  run(&mut d,&mut f,&mut p,"var oldParent=source.parentNode,oldFirst=source.firstChild,oldText=source.textContent,oldValue=source.getAttributeNode('value');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let retained=p.state.retained;let commits=p.state.dom_commits;let attr_count=p.state.attributes.len();let detached=p.state.detached_nodes.clone();let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};
  let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{tag}/{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),(retained,commits,attr_count,detached));assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
  p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==oldParent||source.firstChild!==oldFirst||source.textContent!==oldText||source.getAttributeNode('value')!==oldValue||watch.takeRecords().length)throw 'atomic list-item lifecycle refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,if operation=="promote"{"var records=watch.takeRecords();if(result!==source||source.parentNode!==target||source.firstChild!==oldFirst||source.getAttributeNode('value')!==oldValue||records.length!==1||records[0].addedNodes[0]!==source)throw 'promotion recovery';"}else{"if(result===source||result.parentNode!==null||result.value!==source.value||result.textContent!==source.textContent||source.parentNode!==oldParent||watch.takeRecords().length)throw 'copy recovery';"});
 }}}
}


#[test]
fn li_value_reserved_main_connection_needs_no_additional_node_slots(){
 for tag in ["li"]{for inert_owner in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,owner={},source=owner.createElementNS('http://www.w3.org/1999/xhtml','{tag}');source.value=42;source.appendChild(owner.createTextNode('Reserved'));var first=source.firstChild,attr=source.getAttributeNode('value');",if inert_owner{"new Document()"}else{"document"}));let nodes=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"if(target.appendChild(source)!==source||source.ownerDocument!==document||source.firstChild!==first||source.getAttributeNode('value')!==attr||source.value!==42||source.parentNode!==target)throw 'reserved native list-item connection';");assert_eq!(d.nodes.len(),nodes);p.state.node_limit=limit;}}
}


#[test]
fn li_value_clone_import_active_content_guards_preserve_source(){
 let(mut d,mut f,mut p)=fixture();for node in &mut d.nodes{if let NodeKind::Element{tag,attrs,..}=&mut node.kind{if tag=="li"{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=1".to_owned())});}}}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','li'),frame=doc.createElementNS('http://www.w3.org/1999/xhtml','iframe');source.appendChild(frame);");for code in ["x.cloneNode(true);","document.importNode(source,true);"]{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("support")||e.contains("unavailable")||e.contains("implemented"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.firstChild!==frame||frame.parentNode!==source||source.ownerDocument!==doc||x.value!==-7)throw 'active content copy guard';");}
}

